"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[2857],{2063(e){e.exports=JSON.parse('{"title":"2026\ub144\uc5d0 \uc54c\uba74 \uc88b\uc740 JS \uc9c0\uc2dd","date":"2026-04-13","coverUrl":"/kudzu-based-bench/assets/notion/3ed154d41fa4dd94.png","html":"<h1 data-notion-block-id=\\"33ae548d-8a8e-8089-accd-c6ed3e759600\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"33ae548d-8a8e-80f6-abae-eb396f051e4f\\" id=\\"33ae548d-8a8e-80f6-abae-eb396f051e4f\\">2026\ub144\uc5d0 \uc54c\uba74 \uc88b\uc740 JS \uc9c0\uc2dd</h2><a href=\\"https://frontendmasters.com/blog/what-to-know-in-javascript-2026-edition/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/what-to-know-in-javascript-2026-edition/</a><p data-notion-block-id=\\"340e548d-8a8e-8063-9b09-d138a8e45a70\\">JS\uc758 \uc2e0\uae30\ub2a5\ubd80\ud130 \uc2dc\uc791\ud574\uc11c \ud504\ub808\uc784\uc6cc\ud06c/\ub7f0\ud0c0\uc784/\u2026\uae4c\uc9c0 \ubaa8\ub4e0 \uc0dd\ud0dc\uacc4\uc5d0 \ubb34\uc2a8 \uc77c\uc774 \uc788\uc5c8\ub294\uc9c0 \ud55c \ub208\uc5d0 \uc815\ub9ac\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub108\ubb34 \ub9ce\uc740 \uc815\ubcf4\uc640 \uc2e0\uae30\uc220\uc5d0 \uc555\ub3c4\ub418\uc5c8\ub2e4\uba74, \uc774 \uae00\uc744 \ubcf4\uace0 \uc5b4\ub5a4 \uc77c\uc774 \uc788\uc5c8\ub294\uc9c0 \uac04\ub2e8\ud558\uac8c \ubcf4\ub294 \uac83\uc774 \uc88b\uc544\ubcf4\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"33de548d-8a8e-80fe-b898-d59fe6fb195a\\" id=\\"33de548d-8a8e-80fe-b898-d59fe6fb195a\\">React Native\uc5d0\uc11c JSI\ub294 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uac00</h2><a href=\\"https://heartit.tech/react-native-jsi-deep-dive-part-1-the-runtime-you-never-see/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://heartit.tech/react-native-jsi-deep-dive-part-1-the-runtime-you-never-see/</a><p data-notion-block-id=\\"33ce548d-8a8e-8020-bb6b-ec223db06fe8\\">React Native\ub294 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uac00\ubd80\ud130 \uc2dc\uc791\ud574\uc11c \uc65c JSI\uac00 \ud0c4\uc0dd\ud588\ub294\uc9c0, \uadf8\ub9ac\uace0 JSI\ub97c \uc2e4 \ud658\uacbd\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ub418\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uc2dc\ub9ac\uc988\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/f1e3d4db-0127-4a32-865b-ffd34e238148#ac6bea7e-2bfd-4b67-be63-45c4aa20c804\\">React Native \uc6a9\uc5b4\uc5d0 \ub300\ud55c \uac04\ub2e8\ud55c \uc18c\uac1c</a>\ub97c \ubcf4\uace0 \uc774 \ud30c\ud2b8\ub97c \ubcf4\uba74\uc11c React Native\uac00 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0 \uac10\uc744 \uc7a1\uc73c\uba74 \uc88b\uaca0\ub124\uc694 \ud83d\ude42</p><h2 data-notion-block-id=\\"340e548d-8a8e-809f-a060-e631ce138bc9\\" id=\\"340e548d-8a8e-809f-a060-e631ce138bc9\\">Axios \uacf5\uae09\ub9dd \uacf5\uaca9 \uc0ac\ud6c4 \ud68c\uace0</h2><a href=\\"https://github.com/axios/axios/issues/10636\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/axios/axios/issues/10636</a><p data-notion-block-id=\\"33ee548d-8a8e-8057-81da-fc6d4181d316\\">\uc774\uc804 <a href=\\"https://ones-to-watch.ethansup.net/news/post/336e548d-8a8e-80dd-8fac-d31fea283246#336e548d-8a8e-80f9-9088-e7020729a50e\\">Axios \uacf5\uae09\ub9dd \uacf5\uaca9</a>\uc758 \uc0ac\ud6c4 \ud68c\uace0 \uc774\uc288\uc785\ub2c8\ub2e4. \uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub4ef\uc774 <a href=\\"https://ones-to-watch.ethansup.net/news/post/2c6e548d-8a8e-80b8-b96f-c0656a397504#2cae548d-8a8e-8034-a280-c0782647987d\\">pnpm\uc73c\ub85c \uacf5\uae09\ub9dd \uacf5\uaca9\uc758 \ubc29\ud654\ubcbd \uc138\uc6b0\uae30</a>\ub3c4 \uc88b\uc740 \uae00\uc774\uc9c0\ub9cc, \ubcf5\uc7a1\ud558\ub2e4\uace0 \uc0dd\uac01\ub41c\ub2e4\uba74 <a href=\\"https://daniakash.com/posts/simplest-supply-chain-defense/\\">\uc124\uc815 \ud55c \uc904\ub85c \uacf5\uae09\ub9dd \uacf5\uaca9 \ucd5c\uc18c\ud654\ud558\uae30</a> \uae00 \ub610\ud55c \ubcf4\ub294 \uac83\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4(\ub2e4\ub978 \uc5b8\uc5b4\uc758 \ubc29\uc5b4\ucc45\ub3c4 \uc18c\uac1c\ud569\ub2c8\ub2e4).</p><h2 data-notion-block-id=\\"340e548d-8a8e-803a-9f68-d43f41b36b7d\\" id=\\"340e548d-8a8e-803a-9f68-d43f41b36b7d\\">useEffect \ub300\uc2e0.</h2><a href=\\"https://neciudan.dev/you-really-really-dont-need-an-effect\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://neciudan.dev/you-really-really-dont-need-an-effect</a><p data-notion-block-id=\\"340e548d-8a8e-801b-b5d2-dbc58d5596bc\\">useEffect \ub300\uc2e0 \ub2e4\ub978 \ud328\ud134\uc744 \uc0ac\uc6a9\ud558\ub294 \uac83\uc744 \uad8c\uc7a5\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/204e548d-8a8e-8012-8172-d82bbf268878#20ce548d-8a8e-80ee-8362-d948636debed\\">useSyncExternalStore\uc740 \ub2e4\ub978 \ub9ce\uc740 \ubd80\ubd84\uae4c\uc9c0 \uace0\ub824\ud574\uc57c \ud558\ubbc0\ub85c</a> \ub2e4\ub978 \ub77c\uc774\ube0c\ub7ec\ub9ac \uce21\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud558\ub294\uc9c0 \ubcf4\uace0(Tanstack Query, Tanstack Store, \u2026) \uc790\uc2e0\uc758 \uc0c1\ud669\uc5d0 \ub9de\uac8c \uc0ac\uc6a9\ud558\ub294 \uac83\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"33ae548d-8a8e-802a-b309-e4e478526267\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"340e548d-8a8e-8076-ba5e-df49a6980b87\\" id=\\"340e548d-8a8e-8076-ba5e-df49a6980b87\\">MDN\uc758 React to Lit</h2><a href=\\"https://developer.mozilla.org/en-US/blog/mdn-front-end-deep-dive/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developer.mozilla.org/en-US/blog/mdn-front-end-deep-dive/</a><p data-notion-block-id=\\"340e548d-8a8e-80f5-9bb3-e5ed57ad492b\\">MDN\uc758 \uc0ac\uc774\ud2b8\ub97c React \uae30\ubc18 \uc544\ud0a4\ud14d\ucc98\uc5d0\uc11c Web component\uae30\ubc18\uc778 Lit\uc73c\ub85c \ubc14\uafe8\uace0 \uc65c \ubc14\uafe8\ub294\uc9c0, \uadf8\ub9ac\uace0 \ubc14\uafb8\uba74\uc11c \ub9cc\ub09c \uc694\uad6c\uc0ac\ud56d\ub4e4\uc744 \uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"340e548d-8a8e-80de-be71-daebdb28eb04\\" id=\\"340e548d-8a8e-80de-be71-daebdb28eb04\\">Github diff \ud654\uba74 \ucd5c\uc801\ud654</h2><a href=\\"https://github.blog/engineering/architecture-optimization/the-uphill-climb-of-making-diff-lines-performant/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.blog/engineering/architecture-optimization/the-uphill-climb-of-making-diff-lines-performant/</a><p data-notion-block-id=\\"340e548d-8a8e-809e-90c2-eb5618dc64e9\\">\uc5c4\uccad \ud070 \ub0b4\uc6a9\uc774 \ubcf4\uc5ec\uc838\uc57c \ud558\ub294 \uacbd\uc6b0 \uac00\uc0c1\ud654 \uc678\uc5d0\ub3c4 \ucc98\ub9ac\ud574\uc57c \ud558\ub294 \uac83\ub4e4\uc774 \ub9ce\ub2e4\ub294 \uac83\uc744, \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uc9c0 \uac04\ub2e8\ud558\uac8c \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/2bde548d-8a8e-805b-83a0-e7a11b36e1f3#2bfe548d-8a8e-8057-becf-e03feb71cdad\\">Github \uc7ac\uad6c\uc131\ud558\uae30, RSC\uc640 CSS\ub85c.</a>\ub3c4 \uac19\uc774 \ubcf4\uc2dc\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"340e548d-8a8e-807d-bd54-c5775c3631dc\\" id=\\"340e548d-8a8e-807d-bd54-c5775c3631dc\\">\ube44\ub3d9\uae30\ub97c \ucde8\uc18c\ud558\uae30 \uc704\ud574\uc11c</h2><a href=\\"https://www.inngest.com/blog/hanging-promises-for-control-flow\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.inngest.com/blog/hanging-promises-for-control-flow</a><p data-notion-block-id=\\"340e548d-8a8e-804a-8ac4-c6987e72fad2\\">\ube44\ub3d9\uae30 workflow \ud568\uc218\ub97c \ucde8\uc18c \uac00\ub2a5\ud558\ub3c4\ub85d \ub9cc\ub4e4\uae30 \uc704\ud574\uc11c throw \ubc29\uc2dd\uacfc generator \ubc29\uc2dd\uc5d0 \ubb34\uc2a8 \ubb38\uc81c\uac00 \uc788\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc774\ub97c \uc5b4\ub5bb\uac8c \uad6c\ud604\ud574\uc11c \ud574\uacb0\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub2e8\uacc4\uc801 \uc2e4\ud589\uc774 \ud544\uc694\ud55c \uacbd\uc6b0 \uc88b\uc740 \ub808\ud37c\ub7f0\uc2a4\uac00 \ub420 \uac83 \uac19\ub124\uc694.</p><h2 data-notion-block-id=\\"33de548d-8a8e-80f7-8b84-c101aa19ce78\\" id=\\"33de548d-8a8e-80f7-8b84-c101aa19ce78\\">\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc758 \uae30\ubc18\uc740 \ud658\uacbd\uc774\ub2e4</h2><a href=\\"https://zeroheight.com/blog/why-most-design-systems-fail-at-the-leadership-layer/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://zeroheight.com/blog/why-most-design-systems-fail-at-the-leadership-layer/</a><p data-notion-block-id=\\"33ee548d-8a8e-8048-b6b7-ecf489373875\\">\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc774 \uc131\uacf5\ud558\ub824\uba74 \ub2e8\uc21c\ud788 \uc798 \ub9cc\ub4dc\ub294 \uac83, \uc88b\uc740 \uae30\uc220\uc744 \uc4f0\ub294 \uac83\uc5d0 \uadf8\uce58\uc9c0 \uc54a\uace0 \ud658\uacbd\uc744 \uad6c\ucd95\ud558\ub294 \ub370\uc5d0 \uc788\ub2e4\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"33de548d-8a8e-806f-93e9-e2401b12da82\\" id=\\"33de548d-8a8e-806f-93e9-e2401b12da82\\"><code>!important</code> \uc4f0\uc9c0 \uc54a\uae30</h2><a href=\\"https://css-tricks.com/alternatives-to-the-important-keyword/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://css-tricks.com/alternatives-to-the-important-keyword/</a><p data-notion-block-id=\\"33ce548d-8a8e-8039-89b9-df782ce3dae1\\"><code>!important</code>\uc774 \uc65c \ubb38\uc81c\uac00 \ub418\ub294\uc9c0, \uadf8\ub9ac\uace0 \ucd5c\uc2e0 CSS\ub97c \ud3ec\ud568\ud574\uc11c \uc5b4\ub5bb\uac8c <code>!important</code>\ub97c \uc904\uc77c \uc218 \uc788\uc744\uc9c0 \uc18c\uac1c\ud558\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"340e548d-8a8e-8094-9b27-c6b36c9b5206\\" id=\\"340e548d-8a8e-8094-9b27-c6b36c9b5206\\">Next.js\uc5d0\uc11c Proxy\ub97c \uc0ac\uc6a9\ud574\uc11c \ub3d9\uc801 \ub80c\ub354\ub9c1\uc5d0\uc11c \ubc97\uc5b4\ub098\uae30</h2><a href=\\"https://aurorascharff.no/posts/the-precompute-pattern-encoding-dynamic-data-into-urls-in-nextjs/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://aurorascharff.no/posts/the-precompute-pattern-encoding-dynamic-data-into-urls-in-nextjs/</a><p data-notion-block-id=\\"340e548d-8a8e-80f0-885c-e4973ac528c3\\">Next.js\uc758 <code>cookies()</code>\ub098 <code>headers()</code>\ub97c \uc0ac\uc6a9\ud558\uba74 \ud558\uc704 \ub77c\uc6b0\ud2b8\uac00 \ubaa8\ub450 \ub3d9\uc801 \ub80c\ub354\ub9c1\uc774 \ub418\ub294 \uc0c1\ud669\uc744 proxy\ub97c \uc0ac\uc6a9\ud55c \ud328\ud134\uc744 \ud1b5\ud574 \ud574\uacb0\ud560 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"33de548d-8a8e-8008-9a6a-f805a1c30ca4\\" id=\\"33de548d-8a8e-8008-9a6a-f805a1c30ca4\\"><code>Intl</code> API\ub85c i18n \ud3ec\ub9e4\ud305\ud558\uae30</h2><a href=\\"https://polypane.app/blog/the-intl-api-the-best-browser-api-youre-not-using/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://polypane.app/blog/the-intl-api-the-best-browser-api-youre-not-using/</a><h1 data-notion-block-id=\\"33ae548d-8a8e-80b7-b8b7-d428b2513794\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://boneyard.vercel.app/overview\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://boneyard.vercel.app/overview</a><p data-notion-block-id=\\"340e548d-8a8e-808b-969a-d6afc0bb1af7\\">DOM\uc5d0\uc11c \ucd94\ucd9c\ud55c \uac12\uc744 \uae30\ubc18\uc73c\ub85c skeleton\uc744 \uc0dd\uc131\ud574\uc8fc\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc778 boneyard\uc785\ub2c8\ub2e4.</p><a href=\\"https://www.bram.us/2026/04/02/view-transitions-toolkit/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.bram.us/2026/04/02/view-transitions-toolkit/</a><p data-notion-block-id=\\"33de548d-8a8e-8001-b28d-db6654199adf\\">View Transition\uc744 \uc27d\uac8c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 View Transition Toolkit\uc785\ub2c8\ub2e4.</p><a href=\\"https://tsdown.dev/options/exe\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tsdown.dev/options/exe</a><p data-notion-block-id=\\"340e548d-8a8e-807e-8da1-d60eca133a27\\">rolldown \uae30\ubc18 \uac04\ub2e8\ud55c \ubc88\ub4e4\ub7ec\uc778 tsdown\uc774 Node.js \uae30\ubc18 \ub2e8\uc77c \uc2e4\ud589 \ud30c\uc77c\ub85c \ubc88\ub4e4\ub9c1\ud558\ub294 \uae30\ub2a5\uc744 \ucd94\uac00\ud588\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://discourse.llvm.org/t/rfc-jsir-a-high-level-ir-for-javascript/90456\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://discourse.llvm.org/t/rfc-jsir-a-high-level-ir-for-javascript/90456</a><p data-notion-block-id=\\"340e548d-8a8e-8034-9b03-daac29432d50\\">JS\ud658\uacbd\uc5d0\uc11c\ub294 AST/CFG \uae30\ubc18 \uc624\ud508\uc18c\uc2a4 \ub3c4\uad6c\ub4e4\uc740 \ub9ce\uc740\ub370 IR\uae30\ubc18 \ub3c4\uad6c\ub4e4\uc774 \uc5c6\uae30\uc5d0 \uc0c8\ub85c\uc6b4 RFC\ub97c \ud1b5\ud574 JS \uae30\ubc18 IR\uc778 JSIR\ub97c \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p>"}')}}]);